WITH page_stats AS (SELECT wp_web_page_sk, wp_type, wp_autogen_flag, wp_link_count, wp_char_count, wp_creation_date_sk, wp_rec_start_date, wp_rec_end_date FROM web_page WHERE wp_type = 'article' AND wp_autogen_flag = 'N' AND wp_rec_start_date >= DATE '2023-01-01' AND wp_rec_end_date <= DATE '2023-12-31') SELECT t.t_shift, t.t_hour, COUNT(DISTINCT p.wp_web_page_sk) AS page_count, SUM(p.wp_link_count) AS total_links, AVG(p.wp_char_count) AS avg_char_count, MIN(p.wp_rec_start_date) AS earliest_start_date, MAX(p.wp_rec_end_date) AS latest_end_date FROM time_dim t JOIN page_stats p ON t.t_time_sk = p.wp_creation_date_sk WHERE t.t_hour BETWEEN 6 AND 18 GROUP BY t.t_shift, t.t_hour HAVING COUNT(DISTINCT p.wp_web_page_sk) >= 5 ORDER BY total_links DESC LIMIT 100
